head.script:
scwin.mainClose = function(title) {
    var result = confirm("close?");
    if (result) {
        return true;
    } else {
        return false;
    }
};
scwin.createWindowTest = function(title) {
    wc1.createWindow(title, "", "", "windowTitle", title, "newWindow", scwin.mainClose, null, null);
    //wc1.createWindow( title , iconUrl , src , windowTitle , windowId , openAction , closeAction , windowTooltip, null)
};
scwin.wc1_onbeforecloseall = function() {
    debugger;
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#wc1_subWindow0_header', 'drag-n-drop', {
        dx: 500,
        dy: 0
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc1_subWindow0_header').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wc1_subWindow0').offset().left > 400", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.createWindowTest("main");
    //scwin.createWindowTest("aa");
    //scwin.createWindowTest("bb");
    //scwin.createWindowTest("cc");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
